const safeUrl=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const num=v=>{if(String(v??'').trim()==='')return null;const n=Number(String(v).replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)&&n>=0?n:null};
const money=n=>n===null?'—':new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(n);
