state.collections.forEach(c=>{c.brand=factoryBrand(c.brand)});
Object.keys(state.brands).forEach(b=>{const canonical=factoryBrand(b);if(canonical!==b){state.brandAliasArchive=state.brandAliasArchive||{};state.brandAliasArchive[b]=state.brands[b];const old=state.brands[b],current=state.brands[canonical]||{};state.brands[canonical]={...old,...current};Object.keys(old).forEach(k=>{if(!state.brands[canonical][k])state.brands[canonical][k]=old[k]});delete state.brands[b];}});

